import {claimMediaTask} from './media-task.js?v=20261027windows';
import {createMP4Recorder,verifyMP4} from './mp4-export.js?v=20261027windows';
const $=id=>document.getElementById(id);let running=false;
function wait(el,event,timeout=12000){return new Promise((resolve,reject)=>{const cleanup=()=>{clearTimeout(timer);el.removeEventListener(event,ok);el.removeEventListener('error',bad)},ok=()=>{cleanup();resolve()},bad=()=>{cleanup();reject(Error('媒体无法解码'))};const timer=setTimeout(()=>{cleanup();reject(Error('检查超时'))},timeout);el.addEventListener(event,ok,{once:true});el.addEventListener('error',bad,{once:true})})}
$('runtime-check').onclick=async()=>{if(running)return;let release;try{release=claimMediaTask('检查浏览器兼容性')}catch(e){$('runtime-output').textContent=e.message;return}running=true;$('runtime-check').disabled=true;const states=new Map([...document.querySelectorAll('button,input,select,textarea')].map(e=>[e,e.disabled]));states.forEach((_,e)=>e.disabled=true);const results=[];const row=(name,ok,detail)=>{results.push({name,ok,detail});$('runtime-output').textContent=results.map(r=>`${r.ok?'通过':'未通过'}｜${r.name}：${r.detail}`).join('\n')};let stream,rec,url,video,timer;
 try{
 row('安全连接',window.isSecureContext,window.isSecureContext?'当前处于安全上下文':'请使用网站 HTTPS 地址');
 try{localStorage.setItem('clippilot-runtime-check','1');localStorage.removeItem('clippilot-runtime-check');row('草稿存储',true,'当前浏览器可保存本地草稿')}catch{row('草稿存储',false,'请允许站点存储，或定期下载 JSON 备份')}
 const source=document.createElement('video');source.preload='auto';try{const ready=wait(source,'loadedmetadata');source.src=new URL('./demo/shot1.mp4',import.meta.url).href;await ready;row('MP4 素材解码',Number.isFinite(source.duration)&&source.videoWidth>0,`${source.videoWidth}×${source.videoHeight}；此项只验证内置示例，用户文件可能使用不同编码`)}catch(e){row('MP4 素材解码',false,e.message)}finally{source.removeAttribute('src');source.load()}
 if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream){row('成片编码',false,'浏览器缺少 MediaRecorder 或画布录制，请尝试桌面 Chrome');return}
 
 const canvas=document.createElement('canvas');canvas.width=320;canvas.height=180;const ctx=canvas.getContext('2d');ctx.fillStyle='#334edf';ctx.fillRect(0,0,320,180);stream=canvas.captureStream(20);rec=createMP4Recorder(stream);const mime=rec.mimeType;const chunks=[];
 await new Promise((resolve,reject)=>{rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=resolve;rec.onerror=()=>reject(Error('录制失败'));rec.start(200);let frames=0;timer=setInterval(()=>{ctx.fillStyle=frames%2?'#334edf':'#f4f0e8';ctx.fillRect(0,0,320,180);ctx.fillStyle='#121c36';ctx.font='22px sans-serif';ctx.fillText('ClipPilot '+frames,25,90);if(++frames>=20){clearInterval(timer);rec.stop()}},50)});
 const blob=new Blob(chunks,{type:mime});await verifyMP4(blob);url=URL.createObjectURL(blob);video=document.createElement('video');video.muted=true;const decoded=wait(video,'loadeddata');video.src=url;await decoded;row('成片编码与回读',video.videoWidth===320&&video.videoHeight===180,`${mime}；${blob.size} 字节；${video.videoWidth}×${video.videoHeight}。未验证音轨和完整时间线`);
 row('音频接口',Boolean(window.AudioContext||window.webkitAudioContext),'仅检查接口存在，原音轨仍需实际成片核对');
 }catch(e){row('自检执行',false,e.message)}finally{clearInterval(timer);if(rec&&rec.state!=='inactive')rec.stop();stream?.getTracks().forEach(t=>t.stop());if(video){video.removeAttribute('src');video.load()}if(url)URL.revokeObjectURL(url);running=false;release();states.forEach((disabled,e)=>e.disabled=disabled);$('runtime-check').disabled=false;$('runtime-output').textContent+='\n自检不调用模型、不会上传素材；通过不代表完整产品验收通过。'}
};
